// Convierte el log de auditoria en las tres tablas que piden las pre-entregas.
// Todo lo que sale de aca es rastreable hasta una fila con trace_id: eso es lo que
// diferencia un caso de negocio defendible de una diapositiva con numeros lindos.

const p = $('Parametros del caso de negocio').first().json;
const filas = $input.all().map(i => i.json).filter(r => r && r.trace_id);

if (filas.length === 0) {
  return [{ json: { aviso: 'El log todavia no tiene filas para el entorno ' + p.environment + '. Corre el Manager al menos una vez.' } }];
}

// Una evaluacion = una fila escrita por el agente. Las filas de resolucion humana
// no son evaluaciones nuevas: son la segunda mitad de una que ya se conto.
const evaluaciones = filas.filter(r => r.decidido_por === 'agente');
const resoluciones = filas.filter(r => r.decidido_por === 'humano');
const total = evaluaciones.length;

const cuenta = (campo) => evaluaciones.reduce((acc, r) => {
  const k = r[campo] || 'sin_dato';
  acc[k] = (acc[k] || 0) + 1;
  return acc;
}, {});

// --- KPIs OPERATIVOS (Dimension 1 de la pre-entrega del M9) ---
const autonomas = evaluaciones.filter(r => r.nivel_autonomia === 'AUTONOMO').length;
const con_humano = evaluaciones.filter(r => r.nivel_autonomia === 'APROBACION_HUMANA').length;
const bloqueadas = evaluaciones.filter(r => r.injection_detectada === true).length;
const confianzas = evaluaciones.map(r => Number(r.confianza || 0)).filter(n => n > 0);
const latencias = evaluaciones.map(r => Number(r.latencia_ms || 0)).filter(n => n > 0);
const prom = (a) => a.length ? a.reduce((x, y) => x + y, 0) / a.length : 0;

// --- COSTO (TCO) ---
const costo_total = evaluaciones.reduce((a, r) => a + Number(r.costo_usd || 0), 0);
const costo_prom = total ? costo_total / total : 0;
const tokens_in = evaluaciones.reduce((a, r) => a + Number(r.tokens_in || 0), 0);
const tokens_out = evaluaciones.reduce((a, r) => a + Number(r.tokens_out || 0), 0);

// El escenario real de la mezcla, en vez de multiplicar el peor caso por el volumen.
const escenarios = cuenta('escenario');
const inferencia_mensual = costo_prom * Number(p.volumen_mensual_postulaciones);
const soporte_mensual = Number(p.horas_soporte_mensual) * Number(p.costo_hora_soporte_usd);
const tco_mensual = inferencia_mensual + soporte_mensual + Number(p.retainer_mensual_usd);

// --- BASELINE Y ROI (Dimension 1 del M9 y criterio del M10) ---
// El modulo es explicito: si el cliente no sabe cuanto tarda hoy su equipo, no hay bono.
const horas_manual_mes = (Number(p.minutos_por_cv_a_mano) * Number(p.volumen_mensual_postulaciones)) / 60;
const costo_manual_mes = horas_manual_mes * Number(p.costo_hora_reclutador_usd);
// Los amarillos y las aprobaciones siguen consumiendo tiempo humano, pero de revision (3 min), no de lectura.
const tasa_autonoma = total ? autonomas / total : 0;
const horas_revision_mes = ((1 - tasa_autonoma) * Number(p.volumen_mensual_postulaciones) * 3) / 60;
const costo_revision_mes = horas_revision_mes * Number(p.costo_hora_reclutador_usd);
const ahorro_mensual = costo_manual_mes - costo_revision_mes - tco_mensual;
const roi_mensual = tco_mensual ? ahorro_mensual / tco_mensual : 0;
const payback_meses = ahorro_mensual > 0 ? Number(p.costo_setup_usd) / ahorro_mensual : null;

const r2 = (n) => Math.round(n * 100) / 100;
const r4 = (n) => Math.round(n * 10000) / 10000;

return [{
  json: {
    entorno: p.environment,
    muestra: { evaluaciones: total, resoluciones_humanas: resoluciones.length, filas_totales: filas.length },

    kpis_operativos: {
      tasa_resolucion_autonoma_pct: r2(tasa_autonoma * 100),
      evaluaciones_con_intervencion_humana: con_humano,
      postulaciones_bloqueadas_por_seguridad: bloqueadas,
      confianza_promedio: r2(prom(confianzas)),
      latencia_promedio_seg: r2(prom(latencias) / 1000),
      distribucion_semaforo: cuenta('semaforo')
    },

    matriz_tco: {
      tokens_entrada: tokens_in,
      tokens_salida: tokens_out,
      metodo_costo: 'estimacion_chars_4 (declarado, no medido)',
      costo_por_evaluacion_usd: r4(costo_prom),
      distribucion_escenarios: escenarios,
      proyeccion_1000_evaluaciones_usd: r2(costo_prom * 1000),
      inferencia_mensual_usd: r2(inferencia_mensual),
      soporte_mensual_usd: r2(soporte_mensual),
      retainer_mensual_usd: Number(p.retainer_mensual_usd),
      tco_mensual_usd: r2(tco_mensual)
    },

    caso_de_negocio: {
      baseline_horas_mes: r2(horas_manual_mes),
      baseline_costo_mes_usd: r2(costo_manual_mes),
      horas_de_revision_que_quedan: r2(horas_revision_mes),
      capacidad_liberada_horas_mes: r2(horas_manual_mes - horas_revision_mes),
      ahorro_neto_mensual_usd: r2(ahorro_mensual),
      roi_mensual_pct: r2(roi_mensual * 100),
      payback_meses: payback_meses ? r2(payback_meses) : 'no se recupera con estos supuestos',
      nota: 'La capacidad liberada NO es ahorro en nomina salvo que se reduzca dotacion. Se presenta como capacidad para absorber mas volumen sin sumar gente.'
    },

    advertencia: 'Los costos de inferencia son una ESTIMACION por 4 caracteres = 1 token con precios de ejemplo. Antes de presentar esto a un cliente hay que reemplazarlos por los precios vigentes del proveedor y contrastar contra la factura real.'
  }
}];
